const EXCLUDE_RE = /notes by gemini|weekly meeting|notes for call|meeting notes|call notes|recap notes|^think technologies\s*\|/i;

function cleanName(raw, clientName) {
  let s = String(raw || '').replace(/\.[a-zA-Z0-9]{2,5}$/, '');
  s = s.replace(/_/g, ' ');
  if (clientName) {
    const esc = clientName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    s = s.replace(new RegExp(esc, 'ig'), '');
  }
  s = s.replace(/\bthink technologies\b/ig, '');
  s = s.replace(/\b(final|draft|copy of|v\d+)\b/ig, '');
  s = s.replace(/\s{2,}/g, ' ').trim();
  s = s.replace(/^[-|:\s]+|[-|:\s]+$/g, '').trim();
  if (!s) s = String(raw || '').replace(/\.[a-zA-Z0-9]{2,5}$/, '');
  return s;
}

const clientName = ($('Portal Drive Files Webhook').first().json.body || {}).clientName || '';
const items = $input.all().map(i => i.json).filter(f => f && f.id).filter(f => !EXCLUDE_RE.test(f.name || ''));

// SIGNED-ONLY CONTRACTS (team rule): when a signed PDF of an agreement exists,
// unsigned non-PDF versions of the same agreement are hidden for every client.
const CONTRACT_RE = /contract|agreement|\bmsa\b|statement of work|\bsow\b|engagement letter|\bnda\b|non-disclosure|terms of service/i;
function baseKey(n) {
  return String(n || '').toLowerCase()
    .replace(/\.[a-z0-9]{2,5}$/, '')
    .replace(/copy of/g, '')
    .replace(/[0-9]{1,2}\/[0-9]{1,2}\/[0-9]{2,4}.*$/, '')
    .replace(/[-\u2013\u2014|:,\s]+$/g, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}
const contractPdfKeys = new Set(items.filter(f => CONTRACT_RE.test(f.name || '') && f.mimeType === 'application/pdf').map(f => baseKey(f.name)));
const visibleItems = items.filter(f => {
  if (!CONTRACT_RE.test(f.name || '')) return true;
  if (f.mimeType === 'application/pdf') return true;
  return !contractPdfKeys.has(baseKey(f.name));
});

const files = visibleItems.map(f => ({
  ...f,
  displayName: cleanName(f.name, clientName)
}));
return [{ json: { files } }];

